using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;

// Batch entry point: -executeMethod TotemMeshRecovery.RecoverAll
// Payload is generated by Tools/Recover-TotemMeshes.py from the original APK.
// Existing Mesh objects are updated in place; asset GUIDs and local IDs remain.
public static class TotemMeshRecovery
{
    [Serializable]
    private sealed class Payload
    {
        public int schemaVersion;
        public int expectedMeshCount;
        public MeshData[] records;
    }

    [Serializable]
    private sealed class SubMeshData
    {
        public int[] indices;
        public int sourceTopologyFlag;
        public int sourceTriangleCount;
    }

    [Serializable]
    private sealed class MeshData
    {
        public string assetPath;
        public string guid;
        public long expectedLocalFileId;
        public string metaSha256;
        public string name;
        public int vertexCount;
        public float[] positions;
        public float[] normals;
        public float[] tangents;
        public float[] colors;
        public float[] uv0;
        public float[] uv1;
        public float[] boneWeights;
        public int[] boneIndices;
        public float[] bindposes;
        public SubMeshData[] subMeshes;
        public float[] boundsCenter;
        public float[] boundsSize;
        public int sourceMeshUsageFlags;
    }

    [Serializable]
    private sealed class RecoveryResult
    {
        public string payloadPath;
        public int expectedMeshes;
        public int recoveredMeshes;
        public int verifiedMeshes;
        public int recoveredVertices;
        public int recoveredSkinnedMeshes;
        public int preservedMetaFiles;
        public string status;
        public List<string> errors = new List<string>();
        public List<string> notes = new List<string>();
    }

    [Serializable]
    private sealed class ProbeResult
    {
        public string assetPath;
        public string status;
        public List<string> stages = new List<string>();
        public string error;
    }

    // Small diagnostic/recovery run for the first mesh with a packed color
    // channel. It verifies the saved/reimported asset, not just its live cache.
    public static void ProbeFx1()
    {
        string projectRoot = Directory.GetParent(Application.dataPath).FullName;
        string folder = Path.Combine(Directory.GetParent(projectRoot).FullName, "Analysis/TotemRunner");
        Payload payload = JsonUtility.FromJson<Payload>(File.ReadAllText(Path.Combine(folder, "mesh-recovery-payload.json")));
        MeshData data = Array.Find(payload.records, item => item.assetPath == "Assets/Mesh/FX_1.asset");
        Require(data != null, "FX_1 source payload not found");
        ValidatePayload(data);
        ProbeResult result = new ProbeResult();
        result.assetPath = data.assetPath;
        result.status = "running";
        Mesh rebuilt = null;
        try
        {
            Mesh destination = AssetDatabase.LoadAssetAtPath<Mesh>(data.assetPath);
            Require(destination != null, "FX_1 destination cannot be loaded");
            CheckIdentity(destination, data);
            result.stages.Add(DescribeMesh("initial destination", destination, data));
            rebuilt = BuildMesh(data);
            VerifyMesh(rebuilt, data);
            result.stages.Add(DescribeMesh("validated temporary", rebuilt, data));

            EditorUtility.CopySerialized(rebuilt, destination);
            result.stages.Add(DescribeMesh("after CopySerialized", destination, data));
            ApplyUsageFlags(destination, data);
            result.stages.Add(DescribeMesh("after SerializedObject.ApplyModifiedProperties", destination, data));

            // Rebuild native attributes last. No serialized-object snapshot may
            // subsequently restore the destination's obsolete compressed data.
            PopulateMesh(destination, data);
            VerifyMesh(destination, data);
            result.stages.Add(DescribeMesh("after direct native API refill", destination, data));
            EditorUtility.SetDirty(destination);
            AssetDatabase.SaveAssets();
            AssetDatabase.ForceReserializeAssets(new[] { data.assetPath }, ForceReserializeAssetsOptions.ReserializeAssets);
            AssetDatabase.SaveAssets();
            AssetDatabase.ImportAsset(data.assetPath, ImportAssetOptions.ForceUpdate);
            destination = AssetDatabase.LoadAssetAtPath<Mesh>(data.assetPath);
            VerifyMesh(destination, data);
            CheckIdentity(destination, data);
            Require(HashFile(Path.Combine(projectRoot, data.assetPath + ".meta")) == data.metaSha256, "FX_1 meta changed");
            result.stages.Add(DescribeMesh("after save and forced reimport", destination, data));
            result.status = "success";
            Debug.Log("TOTEM_MESH_FX1_PROBE_SUCCESS " + string.Join(" | ", result.stages));
        }
        catch (Exception exception)
        {
            result.status = "failed";
            result.error = exception.ToString();
            Debug.LogException(exception);
            throw;
        }
        finally
        {
            if (rebuilt != null) UnityEngine.Object.DestroyImmediate(rebuilt);
            File.WriteAllText(Path.Combine(folder, "mesh-recovery-FX1-probe.json"), JsonUtility.ToJson(result, true));
        }
    }

    public static void RecoverAll()
    {
        string projectRoot = Directory.GetParent(Application.dataPath).FullName;
        string workspace = Directory.GetParent(projectRoot).FullName;
        string payloadPath = Path.Combine(workspace, "Analysis/TotemRunner/mesh-recovery-payload.json");
        string[] arguments = Environment.GetCommandLineArgs();
        for (int i = 0; i + 1 < arguments.Length; i++)
            if (arguments[i] == "-totemMeshPayload")
                payloadPath = Path.GetFullPath(arguments[i + 1]);
        string resultPath = Path.Combine(Path.GetDirectoryName(payloadPath), "mesh-recovery-editor-result.json");
        RecoveryResult result = new RecoveryResult();
        result.payloadPath = payloadPath;
        result.status = "running";
        try
        {
            Payload payload = JsonUtility.FromJson<Payload>(File.ReadAllText(payloadPath));
            Require(payload != null && payload.schemaVersion == 1, "Unsupported mesh payload schema");
            Require(payload.records != null && payload.records.Length == payload.expectedMeshCount, "Incomplete mesh payload");
            result.expectedMeshes = payload.expectedMeshCount;
            HashSet<string> paths = new HashSet<string>();
            foreach (MeshData data in payload.records)
            {
                ValidatePayload(data);
                Require(paths.Add(data.assetPath), "Duplicate destination: " + data.assetPath);
                Require(data.assetPath.StartsWith("Assets/Mesh/", StringComparison.Ordinal), "Unexpected mesh destination");
                Require(AssetDatabase.AssetPathToGUID(data.assetPath) == data.guid, "GUID mismatch: " + data.assetPath);
                Require(HashFile(Path.Combine(projectRoot, data.assetPath + ".meta")) == data.metaSha256, "Meta changed since extraction: " + data.assetPath);
            }

            AssetDatabase.StartAssetEditing();
            try
            {
                foreach (MeshData data in payload.records)
                {
                    Mesh destination = AssetDatabase.LoadAssetAtPath<Mesh>(data.assetPath);
                    Require(destination != null, "Mesh asset cannot be loaded: " + data.assetPath);
                    CheckIdentity(destination, data);
                    Mesh rebuilt = BuildMesh(data);
                    try
                    {
                        VerifyMesh(rebuilt, data);
                        rebuilt.hideFlags = destination.hideFlags;
                        EditorUtility.CopySerialized(rebuilt, destination);
                        // CopySerialized alone can leave the imported mesh's native
                        // compressed-channel cache inconsistent (FX_1 lost colors).
                        // Refill the existing native instance and reset its layout.
                        // ApplyUsageFlags is already done on the empty temporary;
                        // do not apply a serialized snapshot after the native refill.
                        PopulateMesh(destination, data);
                        EditorUtility.SetDirty(destination);
                        VerifyMesh(destination, data);
                        CheckIdentity(destination, data);
                        result.recoveredMeshes++;
                        result.recoveredVertices += data.vertexCount;
                        if (data.boneWeights.Length != 0)
                            result.recoveredSkinnedMeshes++;
                    }
                    finally
                    {
                        UnityEngine.Object.DestroyImmediate(rebuilt);
                    }
                }
            }
            finally
            {
                AssetDatabase.StopAssetEditing();
            }

            AssetDatabase.SaveAssets();
            List<string> assetPaths = new List<string>();
            foreach (MeshData data in payload.records)
                assetPaths.Add(data.assetPath);
            AssetDatabase.ForceReserializeAssets(assetPaths, ForceReserializeAssetsOptions.ReserializeAssets);
            AssetDatabase.SaveAssets();
            foreach (MeshData data in payload.records)
            {
                Mesh mesh = AssetDatabase.LoadAssetAtPath<Mesh>(data.assetPath);
                Require(mesh != null, "Saved mesh cannot be loaded: " + data.assetPath);
                VerifyMesh(mesh, data);
                CheckIdentity(mesh, data);
                Require(HashFile(Path.Combine(projectRoot, data.assetPath + ".meta")) == data.metaSha256, "Mesh meta was modified: " + data.assetPath);
                result.preservedMetaFiles++;
                result.verifiedMeshes++;
            }
            result.status = "success";
            result.notes.Add("Original positions, normals, tangents, colors, both UV sets, four skin weights/indices, bindposes, bounds and per-submesh triangles restored.");
            result.notes.Add("No normal/tangent recalculation, coordinate conversion, mesh optimization, scene collider edits or GUID replacements were performed.");
            result.notes.Add("Rebuilt native meshes retain CPU-readable data for verification and physics cooking. This can use more memory than the stripped original build.");
            Debug.Log("TOTEM_MESH_RECOVERY_SUCCESS " + result.recoveredMeshes + " meshes, " + result.recoveredVertices + " vertices, " + result.recoveredSkinnedMeshes + " skinned meshes; " + result.verifiedMeshes + " verified.");
        }
        catch (Exception exception)
        {
            result.status = "failed";
            result.errors.Add(exception.ToString());
            Debug.LogException(exception);
            throw;
        }
        finally
        {
            File.WriteAllText(resultPath, JsonUtility.ToJson(result, true));
        }
    }

    private static Mesh BuildMesh(MeshData data)
    {
        Mesh mesh = new Mesh();
        // Preserve source collision pre-baking requests before native arrays exist.
        ApplyUsageFlags(mesh, data);
        PopulateMesh(mesh, data);
        return mesh;
    }

    private static void PopulateMesh(Mesh mesh, MeshData data)
    {
        mesh.Clear(false);
        MeshUtility.SetMeshCompression(mesh, ModelImporterMeshCompression.Off);
        mesh.name = data.name;
        mesh.indexFormat = data.vertexCount > 65535 ? IndexFormat.UInt32 : IndexFormat.UInt16;
        mesh.vertices = Vector3Array(data.positions);
        if (data.normals.Length != 0) mesh.normals = Vector3Array(data.normals);
        if (data.tangents.Length != 0) mesh.tangents = Vector4Array(data.tangents);
        if (data.colors.Length != 0)
        {
            Color[] colors = new Color[data.vertexCount];
            for (int i = 0; i < colors.Length; i++)
                colors[i] = new Color(data.colors[i * 4], data.colors[i * 4 + 1], data.colors[i * 4 + 2], data.colors[i * 4 + 3]);
            mesh.colors = colors;
        }
        if (data.uv0.Length != 0) mesh.uv = Vector2Array(data.uv0);
        if (data.uv1.Length != 0) mesh.uv2 = Vector2Array(data.uv1);
        if (data.bindposes.Length != 0)
        {
            Matrix4x4[] bindposes = new Matrix4x4[data.bindposes.Length / 16];
            for (int i = 0; i < bindposes.Length; i++)
                for (int row = 0; row < 4; row++)
                    for (int column = 0; column < 4; column++)
                        bindposes[i][row, column] = data.bindposes[i * 16 + row * 4 + column];
            mesh.bindposes = bindposes;
        }
        if (data.boneWeights.Length != 0)
        {
            BoneWeight[] weights = new BoneWeight[data.vertexCount];
            for (int i = 0; i < weights.Length; i++)
            {
                int offset = i * 4;
                weights[i].weight0 = data.boneWeights[offset];
                weights[i].weight1 = data.boneWeights[offset + 1];
                weights[i].weight2 = data.boneWeights[offset + 2];
                weights[i].weight3 = data.boneWeights[offset + 3];
                weights[i].boneIndex0 = data.boneIndices[offset];
                weights[i].boneIndex1 = data.boneIndices[offset + 1];
                weights[i].boneIndex2 = data.boneIndices[offset + 2];
                weights[i].boneIndex3 = data.boneIndices[offset + 3];
            }
            mesh.boneWeights = weights;
        }
        mesh.subMeshCount = data.subMeshes.Length;
        for (int i = 0; i < data.subMeshes.Length; i++)
            mesh.SetTriangles(data.subMeshes[i].indices, i, false);
        mesh.bounds = new Bounds(Vector3Value(data.boundsCenter), Vector3Value(data.boundsSize));
    }

    private static void ApplyUsageFlags(Mesh mesh, MeshData data)
    {
        SerializedObject serialized = new SerializedObject(mesh);
        SerializedProperty usage = serialized.FindProperty("m_MeshUsageFlags");
        if (usage == null) return;
        usage.intValue = data.sourceMeshUsageFlags;
        serialized.ApplyModifiedPropertiesWithoutUndo();
    }

    private static string DescribeMesh(string stage, Mesh mesh, MeshData data)
    {
        string description = stage + ": vertices=" + mesh.vertexCount + ", colors=" + mesh.colors.Length
            + "/" + (data.colors.Length / 4) + ", ColorAttribute=" + mesh.HasVertexAttribute(VertexAttribute.Color)
            + ", compression=" + MeshUtility.GetMeshCompression(mesh);
        Debug.Log("TOTEM_MESH_PROBE " + description);
        return description;
    }

    private static void ValidatePayload(MeshData data)
    {
        Require(data != null && data.vertexCount > 0, "Empty source mesh");
        Require(data.positions != null && data.positions.Length == data.vertexCount * 3, "Missing source positions: " + data.assetPath);
        Require(data.normals != null && data.tangents != null && data.colors != null && data.uv0 != null && data.uv1 != null && data.boneWeights != null && data.boneIndices != null && data.bindposes != null, "Missing attribute arrays");
        CheckLength(data.normals, data.vertexCount * 3, "normals", data);
        CheckLength(data.tangents, data.vertexCount * 4, "tangents", data);
        CheckLength(data.colors, data.vertexCount * 4, "colors", data);
        CheckLength(data.uv0, data.vertexCount * 2, "uv0", data);
        CheckLength(data.uv1, data.vertexCount * 2, "uv1", data);
        CheckLength(data.boneWeights, data.vertexCount * 4, "boneWeights", data);
        Require(data.boneIndices.Length == data.boneWeights.Length && data.bindposes.Length % 16 == 0, "Invalid skin data");
        Require(data.boundsCenter.Length == 3 && data.boundsSize.Length == 3, "Invalid source bounds");
        Require(data.subMeshes != null && data.subMeshes.Length > 0, "Missing source submeshes");
        foreach (SubMeshData submesh in data.subMeshes)
        {
            Require(submesh.indices != null && submesh.indices.Length == submesh.sourceTriangleCount * 3, "Original triangle-count mismatch");
            foreach (int index in submesh.indices)
                Require(index >= 0 && index < data.vertexCount, "Triangle index outside vertex array");
        }
    }

    private static void CheckLength(float[] values, int expected, string label, MeshData data)
    {
        Require(values.Length == 0 || values.Length == expected, "Partial " + label + ": " + data.assetPath);
        foreach (float value in values)
            Require(!float.IsNaN(value) && !float.IsInfinity(value), "Non-finite " + label);
    }

    private static void VerifyMesh(Mesh mesh, MeshData data)
    {
        Require(mesh.vertexCount == data.vertexCount && mesh.HasVertexAttribute(VertexAttribute.Position), "Position channel not restored: " + data.assetPath);
        Verify(Vector3Array(data.positions), mesh.vertices, "positions", data.assetPath);
        Verify(Vector3Array(data.normals), mesh.normals, "normals", data.assetPath);
        Verify(Vector4Array(data.tangents), mesh.tangents, "tangents", data.assetPath);
        Verify(Vector2Array(data.uv0), mesh.uv, "uv0", data.assetPath);
        Verify(Vector2Array(data.uv1), mesh.uv2, "uv1", data.assetPath);
        Color[] colors = mesh.colors;
        Require(colors.Length * 4 == data.colors.Length, "Color-count mismatch: " + data.assetPath
            + " actual=" + colors.Length + " expected=" + (data.colors.Length / 4)
            + " ColorAttribute=" + mesh.HasVertexAttribute(VertexAttribute.Color));
        for (int i = 0; i < colors.Length; i++)
        {
            Require(Close(colors[i].r, data.colors[i * 4]) && Close(colors[i].g, data.colors[i * 4 + 1]) && Close(colors[i].b, data.colors[i * 4 + 2]) && Close(colors[i].a, data.colors[i * 4 + 3]), "Color mismatch: " + data.assetPath);
        }
        Require(mesh.subMeshCount == data.subMeshes.Length, "Submesh-count mismatch: " + data.assetPath);
        for (int i = 0; i < data.subMeshes.Length; i++)
        {
            int[] actual = mesh.GetTriangles(i);
            int[] expected = data.subMeshes[i].indices;
            Require(actual.Length == expected.Length, "Triangle-count mismatch: " + data.assetPath);
            for (int j = 0; j < actual.Length; j++)
                Require(actual[j] == expected[j], "Triangle topology mismatch: " + data.assetPath);
        }
        BoneWeight[] weights = mesh.boneWeights;
        Require(weights.Length * 4 == data.boneWeights.Length, "Skin-count mismatch: " + data.assetPath);
        for (int i = 0; i < weights.Length; i++)
        {
            int j = i * 4;
            Require(Close(weights[i].weight0, data.boneWeights[j]) && Close(weights[i].weight1, data.boneWeights[j + 1]) && Close(weights[i].weight2, data.boneWeights[j + 2]) && Close(weights[i].weight3, data.boneWeights[j + 3]), "Skin-weight mismatch: " + data.assetPath);
            Require(weights[i].boneIndex0 == data.boneIndices[j] && weights[i].boneIndex1 == data.boneIndices[j + 1] && weights[i].boneIndex2 == data.boneIndices[j + 2] && weights[i].boneIndex3 == data.boneIndices[j + 3], "Bone-index mismatch: " + data.assetPath);
        }
        Matrix4x4[] matrices = mesh.bindposes;
        Require(matrices.Length * 16 == data.bindposes.Length, "Bindpose-count mismatch: " + data.assetPath);
        for (int i = 0; i < matrices.Length; i++)
            for (int row = 0; row < 4; row++)
                for (int column = 0; column < 4; column++)
                    Require(Close(matrices[i][row, column], data.bindposes[i * 16 + row * 4 + column]), "Bindpose mismatch: " + data.assetPath);
        Require((mesh.bounds.center - Vector3Value(data.boundsCenter)).sqrMagnitude < 0.0001f && (mesh.bounds.size - Vector3Value(data.boundsSize)).sqrMagnitude < 0.0001f, "Bounds mismatch: " + data.assetPath);
    }

    private static void CheckIdentity(Mesh mesh, MeshData data)
    {
        string guid;
        long localId;
        Require(AssetDatabase.TryGetGUIDAndLocalFileIdentifier(mesh, out guid, out localId) && guid == data.guid && localId == data.expectedLocalFileId, "Mesh identity changed: " + data.assetPath);
    }

    private static bool Close(float a, float b)
    {
        return Mathf.Abs(a - b) <= 0.000001f * Mathf.Max(1f, Mathf.Abs(b));
    }

    private static void Verify<T>(T[] expected, T[] actual, string label, string path)
    {
        Require(expected.Length == actual.Length, label + " count mismatch: " + path);
        EqualityComparer<T> comparer = EqualityComparer<T>.Default;
        for (int i = 0; i < expected.Length; i++)
            Require(comparer.Equals(expected[i], actual[i]), label + " mismatch: " + path + " at " + i);
    }

    private static Vector2[] Vector2Array(float[] values)
    {
        Vector2[] result = new Vector2[values.Length / 2];
        for (int i = 0; i < result.Length; i++) result[i] = new Vector2(values[i * 2], values[i * 2 + 1]);
        return result;
    }

    private static Vector3[] Vector3Array(float[] values)
    {
        Vector3[] result = new Vector3[values.Length / 3];
        for (int i = 0; i < result.Length; i++) result[i] = new Vector3(values[i * 3], values[i * 3 + 1], values[i * 3 + 2]);
        return result;
    }

    private static Vector4[] Vector4Array(float[] values)
    {
        Vector4[] result = new Vector4[values.Length / 4];
        for (int i = 0; i < result.Length; i++) result[i] = new Vector4(values[i * 4], values[i * 4 + 1], values[i * 4 + 2], values[i * 4 + 3]);
        return result;
    }

    private static Vector3 Vector3Value(float[] values)
    {
        return new Vector3(values[0], values[1], values[2]);
    }

    private static string HashFile(string path)
    {
        using (SHA256 hash = SHA256.Create())
            return BitConverter.ToString(hash.ComputeHash(File.ReadAllBytes(path))).Replace("-", "").ToLowerInvariant();
    }

    private static void Require(bool condition, string message)
    {
        if (!condition) throw new InvalidDataException(message);
    }
}
